InstrSql:
SELECT  :SN3 INTO :NRF FROM DUAL;

SELECT CASE WHEN :SN1 =  1 THEN 'Concluídas. '  END INTO :LTF FROM DUAL;

SELECT CASE WHEN :SN2 =  1 THEN 'Produtivos. '  END INTO :LTG FROM DUAL;

SET LS1_CMD = ' EMP.NOMEREDUZIDO = :LS1 AND';

SET LS3_CMD = " AND ((EXISTS (SELECT 1 FROM IV_CLIENTEATRIB WHERE ATRIBUTO = 'PERFIL CLIENTE SERVIÇOS' AND LISTA = '#LS3' AND SEQPESSOA = HIS.SEQPESSOA) AND '#LS3' <> 'FATURAMENTO ABAIXO DE 30 MIL') OR (NOT EXISTS (SELECT 1 FROM IV_CLIENTEATRIB WHERE ATRIBUTO = 'PERFIL CLIENTE SERVIÇOS' AND SEQPESSOA = HIS.SEQPESSOA) AND '#LS3' = 'FATURAMENTO ABAIXO DE 30 MIL'))";

SET LS4_CMD = " AND NOT EXISTS (SELECT 1 FROM IV_CLIENTEATRIB WHERE SEQPESSOA = HIS.SEQPESSOA AND ATRIBUTO = 'PERFIL CLIENTE SERVIÇOS' ) AND :LS3 = 'FATURAMENTO ABAIXO DE 30 MIL'";

SELECT CASE WHEN :LS4 ='Serviço' THEN '940027' WHEN :LS4 ='Máquina' THEN '940006' WHEN :LS4 ='Peça' THEN '940030' ELSE '940030, 940006, 940027' END INTO :LTE;

SELECT CASE :SN1 WHEN 1 THEN '  AND RES.CONCLUSIVO = ' + CHAR(39) + 'S'  + CHAR(39) ELSE '' END INTO :LTA FROM DUAL;

SELECT CASE :SN2 WHEN 1 THEN '  AND RES.RESULTADO IN (285, 286, 940126, 940127, 940133, 940134)' ELSE '' END INTO :LTB FROM DUAL;

SELECT CASE :LS2 WHEN 'Diária' THEN 'LEFT(CONVERT (VARCHAR(10), HIS.DTAREALIZACAO, 103), 5)' 
                                  WHEN 'Semanal' THEN CHAR(39) + 'Sem ' + CHAR(39) + ' + CAST ( DATEPART ( WK, HIS.DTAREALIZACAO ) - DATEPART(WK, :DT1) + 1 AS VARCHAR )'
                                  ELSE CHAR(39) + 'Mês ' + CHAR(39) + ' + SUBSTRING( CAST ( DATEPART ( month, HIS.DTAREALIZACAO ) + 100 AS VARCHAR ), 2, 2)' END INTO :LTC FROM DUAL;

SELECT HIS.NROEMPRESA AS EMPRESA,  
       EMP.NOMEREDUZIDO AS DESCEMPRESA,
       CONVERT(VARCHAR(10), HIS.DTAREALIZACAO, 103) AS DATA,
       #LTC AS VISAO,
       HIS.RESULTADO AS RESULTADO,
       RES.DESCRICAO AS DESCRESULTADO,
       1 AS QTDE,
       PES.NOMERAZAO, 
       HIS.DETALHE AS DETALHE_L, 
       HIS.PROCESSO, 
       HIS.CODUSUARIO
FROM IV_HISTORICO HIS
INNER JOIN IV_RESULTADO RES ON RES.RESULTADO = HIS.RESULTADO #LTA #LTB
INNER JOIN GE_EMPRESA EMP ON EMP.NROEMPRESA = HIS.NROEMPRESA 
INNER JOIN GE_PESSOA PES ON PES.SEQPESSOA = HIS.SEQPESSOA
WHERE #LS1_CMD
              HIS.DTAREALIZACAO >= :DT1
      AND HIS.DTAREALIZACAO <= :DT2
      AND HIS.ACAOGERADORA IN ( #LTE)

#LS3_CMD

ORDER BY RES.RESULTADO, #LTC

exec dbo.PR_PROPRIEDADE;
commit;

SELECT 'SUCESSO' FROM DUAL;

exec dbo.PR_ATUALIZA_TITULO_INATIVO @LinkStr = '#LT1', @Retorno = 'A';
COMMIT;

SELECT 'Procedure Executada'
FROM DUAL;
